use std::fs

fn is_int(t: string) -> bool {
    let mut digits: int = 0
    let mut i: int = 0
    for c in t.chars() {
        if i == 0 && c == '-' {
        } else if c.is_ascii_digit() {
            digits += 1
        } else {
            return false
        }
        i += 1
    }
    digits > 0
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    for t in line.split_whitespace() {
        if t == "+" || t == "-" || t == "*" || t == "/" {
            if st.len() < 2 {
                return "error: underflow"
            }
            let b = st.pop().unwrap_or(0)
            let a = st.pop().unwrap_or(0)
            if t == "+" {
                st.push(a + b)
            } else if t == "-" {
                st.push(a - b)
            } else if t == "*" {
                st.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                st.push(a / b)
            }
        } else if is_int(t) {
            let n: int = t.parse::<int>().unwrap_or(0)
            st.push(n)
        } else {
            return "error: token"
        }
    }
    if st.len() != 1 {
        return "error: leftover"
    }
    "${st[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim().len() == 0 {
            continue
        }
        println(eval(line))
    }
}

